import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxButton,
  JxDivider,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  comment: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  comment: '',
};

export default function RegistrationWizard({
  onSubmit,
}: {
  onSubmit: (data: RegistrationData) => void;
}) {
  const [step, setStep] = useState(0);
  const [touched, setTouched] = useState(false);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) => {
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const nameError = !data.name.trim() ? 'Укажите имя и фамилию' : undefined;
  const emailError = !data.email.trim()
    ? 'Укажите адрес почты'
    : !data.email.includes('@')
      ? 'Адрес должен содержать символ @'
      : undefined;
  const countryError = !data.country ? 'Выберите страну' : undefined;
  const cityError = !data.city.trim() ? 'Укажите город' : undefined;
  const streetError = !data.street.trim() ? 'Укажите улицу и дом' : undefined;

  const stepErrors: Array<Array<string | undefined>> = [
    [nameError, emailError],
    [countryError, cityError, streetError],
    [],
  ];
  const stepIsValid = stepErrors[step].every((error) => !error);

  const show = (error: string | undefined) => (touched ? error : undefined);

  const goBack = () => {
    setTouched(false);
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const goNext = () => {
    if (!stepIsValid) {
      setTouched(true);
      return;
    }
    setTouched(false);
    setStep((prev) => Math.min(prev + 1, steps.length - 1));
  };

  const countryLabel = countries.find((item) => item.value === data.country)?.label ?? '—';

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (step < steps.length - 1) {
          goNext();
          return;
        }
        onSubmit(data);
      }}
      style={{ display: 'grid', gap: '24px', maxWidth: '520px' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Имя и фамилия"
            required
            autoComplete="name"
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
            errorText={show(nameError)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={show(emailError)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            autoComplete="tel"
            helperText="Необязательно, для связи по доставке"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          {show(countryError) ? (
            <JxAlert intent="danger" title="Страна не выбрана">
              {countryError}
            </JxAlert>
          ) : null}
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
            errorText={show(cityError)}
          />
          <JxInputField
            label="Улица и дом"
            required
            autoComplete="street-address"
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
            errorText={show(streetError)}
          />
          <JxTextareaField
            label="Комментарий к адресу"
            rows={3}
            maxLength={300}
            helperText={`${data.comment.length}/300`}
            value={data.comment}
            onChange={(event) => set('comment', event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxAlert intent="info" title="Проверьте данные">
            После отправки изменить анкету можно будет только в профиле.
          </JxAlert>
          <JxDivider label="Контакты" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
              color: 'var(--jx-text)',
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.name}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.email}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Телефон</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>
              {data.phone ? `+7 ${data.phone}` : 'Не указан'}
            </dd>
          </dl>
          <JxDivider label="Адрес" />
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
              color: 'var(--jx-text)',
            }}
          >
            <dt style={{ color: 'var(--jx-text-2)' }}>Страна</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{countryLabel}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.city}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Улица и дом</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.street}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Комментарий</dt>
            <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{data.comment || 'Нет'}</dd>
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" type="button" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="submit">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

